"import os

def w(path, text):
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    with open(path, "w") as f:
        f.write(text)

# Domain and physical parameters
LX, LY, LZ = 9.0, 1.0, 2.0          # domain extents (m)
T_HOT, T_COLD = 305.0, 290.0        # hot wall (bottom) / cold wall (top) temperatures (K)
DT, END, WRITE = 1.0, 1000.0, 50.0  # time step (s) / end time (s) / write interval (s)

# Control dictionary: drives the buoyantFoam simulation
w("system/controlDict", f"""FoamFile {{ version 2.0; format ascii; class dictionary; object controlDict; location "system"; }}
application     buoyantFoam;
startFrom       startTime;
startTime       0;
stopAt          endTime;
endTime         {END};
deltaT          {DT};
writeControl    runTime;
writeInterval   {WRITE};
purgeWrite      0;
writeFormat     ascii;
writePrecision  6;
timeFormat      general;
timePrecision   6;
runTimeModifiable true;
""")

# Finite-volume discretisation schemes (stable defaults for buoyantFoam with bounded linear)
w("system/fvSchemes", """FoamFile { version 2.0; format ascii; class dictionary; object fvSchemes; location "system"; }
ddtSchemes { default Euler; }
gradSchemes { default Gauss linear; grad(p_rgh) Gauss linear; }
divSchemes
{
    default none;
    div(phi,U)  bounded Gauss limitedLinear 0.2;
    div(phi,h)  bounded Gauss limitedLinear 0.2;
    div(phi,K)  bounded Gauss limitedLinear 0.2;
    div(phi,T)  bounded Gauss limitedLinear 0.2;
    div(((rho*nuEff)*dev2(T(grad(U))))) Gauss linear;
}
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected; }
""")

# Linear solvers + PIMPLE loop settings
w("system/fvSolution", """FoamFile { version 2.0; format ascii; class dictionary; object fvSolution; location "system"; }
solvers
{
    p_rgh
    {
        solver          GAMG;
        tolerance       1e-7;
        relTol          0.01;
        smoother        DICGaussSeidel;
    }
    p_rghFinal
    {
        solver          GAMG;
        tolerance       1e-7;
        relTol          0;
        smoother        DICGaussSeidel;
    }
    "(U|h|k|epsilon|omega)"
    {
        solver          PBiCGStab;
        preconditioner  DILU;
        tolerance       1e-8;
        relTol          0.1;
    }
    "(U|h|k|epsilon|omega)Final"
    {
        solver          PBiCGStab;
        preconditioner  DILU;
        tolerance       1e-8;
        relTol          0;
    }
    "(rho|rhoFinal)"
    {
        solver          PBiCGStab;
        preconditioner  DILU;
        tolerance       1e-8;
        relTol          0;
    }
}
PIMPLE
{
    momentumPredictor        no;
    nNonOrthogonalCorrectors 0;
    pRefCell                 0;
    pRefValue                0;
}
potentialFlow
{
    nNonOrthogonalCorrectors 10;
}
relaxationFactors
{
    equations
    {
        ".*" 1;
    }
}
""")

# blockMeshDict: single hex block, 2D-like (empty frontAndBack with 1 cell thick in y)
